mapper.select:
SELECT ft.id, ft.task_no, ft.patient_id, p.name AS patient_name, ft.doctor_id, u.name AS doctor_name, ft.task_type, ft.task_content, ft.plan_date, ft.actual_date, ft.status, ft.priority, ft.creator_id, u2.name AS creator_name, ft.assign_date, ft.remarks, CASE ft.status WHEN 'pending' THEN '待办' WHEN 'in_progress' THEN '进行中' WHEN 'completed' THEN '已完成' WHEN 'cancelled' THEN '已取消' ELSE ft.status END AS status_name, CASE ft.priority WHEN 'low' THEN '低' WHEN 'normal' THEN '正常' WHEN 'high' THEN '高' ELSE ft.priority END AS priority_name FROM followup_task ft LEFT JOIN patient p ON ft.patient_id = p.id LEFT JOIN doctor d ON ft.doctor_id = d.id LEFT JOIN user u ON d.user_id = u.id LEFT JOIN user u2 ON ft.creator_id = u2.id
AND ft.patient_id = #{patientId}
AND ft.doctor_id = #{doctorId}
AND ft.status = #{status}
AND ft.plan_date >= #{startDate}
AND ft.plan_date <= #{endDate}
ORDER BY ft.plan_date ASC, ft.create_time DESC LIMIT #{offset}, #{limit}

SELECT COUNT(*)
FROM followup_task ft


        AND ft.patient_id = #{patientId}


        AND ft.doctor_id = #{doctorId}


        AND ft.status = #{status}


        AND ft.plan_date >= #{startDate}


        AND ft.plan_date <= #{endDate}

mapper.update:
UPDATE followup_task
patient_id = #{patientId}, doctor_id = #{doctorId}, task_type = #{taskType}, task_content = #{taskContent}, plan_date = #{planDate}, actual_date = #{actualDate}, status = #{status}, priority = #{priority}, assign_date = #{assignDate}, remarks = #{remarks},
WHERE id = #{id}

UPDATE followup_task
SET status = #{status}

    , actual_date = CURDATE()

WHERE id = #{id}
